package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 1000000007

var dp [2020][2020]int64

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m, k int
	fmt.Fscan(in, &n, &m, &k)

	limit := n
	if m > limit {
		limit = m
	}

	for i := 0; i < limit; i++ {
		for j := 0; j <= i; j++ {
			if j == 0 {
				dp[j][i] = 1
			} else {
				dp[j][i] = (dp[j][i-1] + dp[j-1][i-1]) % MOD
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[2*k][n-1]*dp[2*k][m-1]%MOD)
}

